[TFMDocumentType(classStr(TFMPostAdhocRegistration), 'PickToteForShipping'), TFMDocumentType(classStr(TFMPostAdhocRegistration), 'shipSelectedTotes'),
TFMMenu('ShipTotes',"@SYS88262","@SYS88262",resourceStr(MobShipping),true,true,['Outbound']),
    TFMMenu('PickToteForShipping',"@MobileWMS:PickOutboundlicenseplateforshipping","@MobileWMS:PickOutboundlicenseplateforshipping",resourceStr(MobShipping),false,true),
    TFMPageLineAdhocRequest(methodStr(MobDocShipTotes, ShipSelectedTotes), '@{ShipSelected}','postIcon',true),
    TFMOrderListGetOrdersDocumentType('ShipTotes',methodStr(MobDocShipTotes,GetShippingToteOrders))]
class MobDocShipTotes extends TFMDocumentHandler
{
    XML							returningXML;
    NoYes						shipUnstaged;
}

