[TFMParameter(NoYes::No,"@MobileWMS:ShipUnstagedOutboundLicensePlates")]
public MobPromptForUnit parmShipUnstaged(MobPromptForUnit _shipUnstaged = shipUnstaged)
{
    shipUnstaged = _shipUnstaged;
    return shipUnstaged;
}

public Map registerImage()
{
    Map ret = super();
    ret.insert('mainmenushipping',resourceStr(MobShipping));

    return ret;
}

public TFMPages pages()
{
    TFMPages ret = super();
    TFMPageOrderList	listPage = new TFMPageOrderList();
    TFMPageUnplannedItemRegistration page;
    TFMPageUnplannedItemRegistrationConfiguration configuration;
    TFMDataSourceBlockLockOrderList		dsbOrderList = new TFMDataSourceBlockLockOrderList();//Containing IC4

    TFMPageOrderListConfiguration Listconfig;
    listPage.parmId('ShipTotes');
    listPage.parmFilter(methodStr(MobDocShipTotes,ShipTotesFilters));
    listPage.parmIcon('mainmenushipping');
    listPage.parmTitle('@{Shipping}');
    Listconfig = listPage.getConfiguration();

    dsbOrderList.parmUseOrderLocking(false);
    listPage.addDataSourceBlock(dsbOrderList);

    Listconfig.parmNavigateTo('PickToteForShipping');
    listPage.addAdhocAction(methodStr(MobDocShipTotes, ShipSelectedTotes),1);
    ret.addpage(listPage);
    page = ret.getPage('PickToteForShipping');
    configuration = page.getConfiguration();
    configuration.parmClose(true);

    ret.removePage('shipSelectedTotes');

    return ret;
}

/// <summary>
/// Sets up the filter used on the pick orders page.
/// </summary>
/// <returns>An XML string with the fields to be used for the filter.</returns>
[TFMReferenceDataMethod]
public TFMReferenceData ShipTotesFilters()
{
    TFMReferenceDataConfiguration   refData = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorList    regCollectorList = TFMGetReferenceData::createDefaultWarehouseReferenceData(1);
    TFMRegistrationCollectorDate    regCollectorDate = TFMRegistrationCollector::collectorFromEDT(extendedtypestr(WMSRequestedShipDate));
    TFMRegistrationCollectorList    regCollectorDlv = new TFMRegistrationCollectorList(5, extendedtypestr(DlvModeId), "@SYS50767", "@SYS50767", "@SYS50767"); //TFMRegistrationCollector::collectorFromEDT(extendedtypestr(DlvModeId));
    //TFMRegistrationCollectorText	refCol = new TFMRegistrationCollectorText(40,tableStr(ReferenceIdentity),"@SYS15217","@SYS15217", "@SYS15217");
    refData.addCollector(regCollectorList);

    regCollectorDate.parmName(MobConstants::DeliveryDate());
    regCollectorDate.isHeader(true);
    refData.addCollector(regCollectorDate);
    regCollectorDlv.parmDataTable(methodStr(MobDocShipTotes,DlvMode ));

    refData.addCollector(regCollectorDlv);
    //refData.parmUseDynaFilter(true);
    return refData;

}

	public str GetShippingToteOrders()
    {
        str                         scannedValue;
        XmlElement                  ordersElement;
        TFMRequestGetOrdersElement  orderRequest = request;
        TFMRequestFiltersElement    filters;
        MobToteTable				totes;
        MobToteContent				content;
        WmsOrderTrans				wmsOrderTrans;
        WMSPickingRoute				route;
        WMSShipment					shipment;
		InventLocationId			inventLocationId = MobConstants::All();
        Date						deliveryDate;
        TFMXMLFormat				xmlFormat;
        //SalesTable					salesTable;
        Set							totesInView = new Set(Types::String);
        SetEnumerator				sEnum;
        int							i = 100;
        DlvModeId					DlvModeId;


        // Create the response XML document where the found orders will be added to
        resultXml   = new XmlDocument();
        ordersElement = resultXml.appendChild(resultXml.createElement(MobConstants::Orders()));

        // Before the search for orders is performed we get the filter values entered on the mobile device
        if (orderRequest.parmFilters() != null)
        {
            filters = orderRequest.parmFilters();

            inventLocationId	= filters.parmWarehouse();
            deliveryDate		= filters.parmDeliveryDate();
            scannedValue		= filters.getFieldValue(MobConstants::ScannedValue());
            DlvModeId			= filters.getFieldValue(extendedTypeStr(DlvModeId));

        }
		/*if (scannedValue)
        {
            TFMMultiSelectionTable::addOrRemoveSelection(curuserid(),request.parmdeviceID(),scannedValue,  classStr(MobDocShipTotes));
        }*/
        while select * from content where content.Qty != 0 && (!scannedValue || scannedValue == content.ToteId)
            join totes where totes.ToteId == content.ToteId && !totes.Shipped && (totes.Status == TFMDocumentQueueStatus::Completed || shipUnstaged)
            join wmsOrderTrans where wmsOrderTrans.RecId == content.RefRecId			
            join route where route.pickingRouteID == wmsOrderTrans.routeId && (route.DlvModeId == DlvModeId || DlvModeId == MobConstants::All()) && route.inventLocationId == inventLocationId
            join shipment where shipment.shipmentId == route.shipmentId && shipment.RequestedShipDate <= deliveryDate 
        {
            totesInView.add(content.ToteId);
        }

        sEnum = totesInView.getEnumerator();
        while (sEnum.moveNext())
        {
            xmlFormat = TFMXMLFormat::constructFromBackendID(tableStr(MobToteTable) + '/' + fieldStr(MobToteTable, ToteId) + '/' + sEnum.current(),classStr(TFMXMLFormatOrders));
            //backendIDcon = MobHelper::strSplit(mEnum.currentKey(),'/').pack();

            xmlFormat.initFromCommon(resultXml,MobToteTable::FindOrCreate(sEnum.current()),(scannedValue == sEnum.current() ? 1 : i) ,'');
            xmlFormat.parmPageID('ShipTotes');
            xmlFormat.run();
            i++;
        }
        returningXML = resultXml.xml();
        returningXML = strReplace(returningXML,'<' + MobConstants::Orders() + '>','');
        returningXML = strReplace(returningXML,'</' + MobConstants::Orders() + '>','');

        resultXml = null;

        return '';
    }

    [TFMDocumentType(classStr(TFMPostAdhocRegistration), 'shipSelectedTotes')]
    public str ShipSelectedTotes()
    {
        SetEnumerator	allSelectedTotes = TFMMultiSelectionTable::GetAllInContext(curUserId(),classStr(MobDocShipTotes),request.parmdeviceID()).getEnumerator();
        MobToteTable	toteTable;
        ttsbegin;
        while (allSelectedTotes.moveNext())
        {
            toteTable = MobToteTable::Find(allSelectedTotes.current(),true);
            toteTable.Shipped = NoYes::Yes;
			if (toteTable)
            {
                toteTable.update();
            }
        }
        ttscommit;
        TFMMultiSelectionTable::RemoveAllInContext(curUserid(),classStr(MobDocShipTotes),request.parmdeviceID());
        Return '';
    }

	[TFMReferenceDataMethod]
    public TFMReferenceData PickToteForShippingFilter()
    {
        TFMReferenceDataConfiguration   refData = new TFMReferenceDataConfiguration();
        TFMRegistrationCollectorText    regCollectorText = TFMRegistrationCollector::collectorFromEDT(extendedtypestr(MobToteId));

        refData.addCollector(regCollectorText);

        return refData;
    }

public XML getResult()
{
    if (resultXml)
    {
        return resultXml.xml();
    }

    return returningXML;
}
